    "start": 26,
    "code": "    def effective_policy(self, session: Optional[SessionStore], session_id: Optional[str]) -> str:\n        if session is None or session_id is None:\n            return self.policy\n        policy = self.policy\n        for event in session.load(session_id):\n            if event[\"type\"] == \"approval/policy\":\n                override = event[\"payload\"].get(\"policy\")\n                if override not in {\"ask\", \"never\"}:\n                    raise ValueError(f\"session contains invalid approval policy: {override}\")\n                policy = override\n        return policy"
